sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float width;
uniform float edgeCut;
uniform float glowSize;
uniform float intensity;
layout(color) uniform half4 coreColor;
layout(color) uniform half4 glowColor;
uniform float coreAmount;
uniform float darkenBase;
uniform float flicker;
uniform float flickerSpeed;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float hash21(float2 p) {
    return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}
float edgeAt(float2 p, float w) {
    float tl = luma(tex(p + float2(-w, -w)).rgb);
    float tc = luma(tex(p + float2(0.0, -w)).rgb);
    float tr = luma(tex(p + float2(w, -w)).rgb);
    float ml = luma(tex(p + float2(-w, 0.0)).rgb);
    float mr = luma(tex(p + float2(w, 0.0)).rgb);
    float bl = luma(tex(p + float2(-w, w)).rgb);
    float bc = luma(tex(p + float2(0.0, w)).rgb);
    float br = luma(tex(p + float2(w, w)).rgb);
    float gx = -tl - 2.0 * ml - bl + tr + 2.0 * mr + br;
    float gy = -tl - 2.0 * tc - tr + bl + 2.0 * bc + br;
    return length(float2(gx, gy));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float core = saturate((edgeAt(coord, width) - edgeCut) * intensity);
    float g1 = edgeAt(coord, glowSize);
    float g2 = edgeAt(coord, glowSize * 2.5);
    float glow = saturate((g1 * 0.7 + g2 * 0.5 - edgeCut) * intensity);
    float fl = 1.0 - flicker * (0.5 + 0.5 * sin(time * flickerSpeed + hash21(float2(floor(time * flickerSpeed), 1.0)) * 6.0));
    float3 o = s * (1.0 - darkenBase);
    o += float3(glowColor.rgb) * glow * fl;
    o += mix(float3(glowColor.rgb), float3(coreColor.rgb), coreAmount) * core * fl;
    return fin(c, float4(max(o, float3(0.0)) * c.a, c.a), opacity);
}
